"""Generator: business + real reviews + real photos -> honest site content.

Design decisions that keep this honest and auditable:

  * Testimonials are NEVER generated by the LLM. They are *selected* from the
    real reviews in code, keeping the verbatim text, the real author and the
    real star rating. The LLM only influences copy that is clearly marketing
    (hero line, service blurbs, about paragraph) -- never the social proof.
  * Everything the LLM produces is validated. Services must be plain strings.
    If the model is unavailable or returns garbage, we fall back to a
    deterministic, category-based template so a build always succeeds.
  * Imagery follows the same rule as copy: the business's own photos are the
    real thing and get the gallery; anything we synthesised is *illustrative*
    decoration, is excluded from the gallery, carries no caption, and is
    disclosed on the page and in ``provenance.json``.
  * A machine-readable provenance record lists exactly which reviews became
    testimonials and where every single image came from, so any claim on the
    page is traceable to source input.
"""
from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Callable, Optional

from reviewforge import images as images_mod
from reviewforge import llm
from reviewforge.models import Business, SiteImage

MAX_TESTIMONIALS = 5
MIN_TESTIMONIALS = 3
TESTIMONIAL_MAX_CHARS = 320

#: Minimum number of business-own photos before we render a gallery section.
#: One lonely photo in a grid looks worse than no grid.
MIN_GALLERY_PHOTOS = 2


@dataclass
class Service:
    title: str
    description: str
    #: Optional imagery for the card. Illustrative unless the business
    #: supplied it.
    image: Optional[SiteImage] = None


@dataclass
class Testimonial:
    author: str
    rating: float
    text: str
    date: Optional[str]
    source_index: Optional[int]
    truncated: bool = False
    source_url: Optional[str] = None


@dataclass
class ImageConfig:
    """How the image layer should behave for one build.

    ``mode``:
      * ``auto``         -- use the business's photos; fall back to generated
                            illustrative imagery only if it supplied none.
      * ``own-only``     -- use the business's photos and nothing else. A
                            text-only page is an acceptable outcome.
      * ``illustrative`` -- force generation even if photos were supplied
                            (useful for previewing the fallback).
      * ``off``          -- no imagery at all.
    """

    mode: str = "auto"
    backend: str = "auto"
    #: None -> images.DEFAULT_COMFYUI_URL / DEFAULT_CHECKPOINT, resolved when
    #: the backend is built rather than baked in as an argument default.
    comfyui_url: Optional[str] = None
    checkpoint: Optional[str] = None
    service_count: int = 3
    seed: Optional[int] = None
    #: Seconds to wait for one generated image (None -> backend default).
    timeout: Optional[float] = None
    #: Directory (inside the output dir) that generated/staged assets land in.
    asset_subdir: str = "images"


@dataclass
class ImageSet:
    """The resolved imagery for a page, plus how it was obtained."""

    hero: Optional[SiteImage] = None
    service_images: list[SiteImage] = field(default_factory=list)
    gallery: list[SiteImage] = field(default_factory=list)
    logo: Optional[SiteImage] = None
    #: Explains the outcome -- backend chosen, attempts, failures, mode.
    info: dict = field(default_factory=dict)

    @property
    def all_images(self) -> list[SiteImage]:
        out: list[SiteImage] = []
        if self.logo:
            out.append(self.logo)
        if self.hero:
            out.append(self.hero)
        out.extend(self.service_images)
        out.extend(self.gallery)
        return out

    @property
    def uses_illustrative(self) -> bool:
        return any(img.illustrative for img in self.all_images)

    @property
    def has_images(self) -> bool:
        return bool(self.all_images)


@dataclass
class SiteContent:
    business: Business
    hero_headline: str
    hero_subhead: str
    services: list[Service]
    about: str
    cta_label: str
    testimonials: list[Testimonial]
    images: ImageSet = field(default_factory=ImageSet)
    #: Heading/intro for the services block. The fallback template's cards are
    #: practical information rather than a service menu, so it says so.
    services_heading: str = "What we do"
    services_intro: str = ""
    # Auditable record of how this page was produced.
    provenance: dict = field(default_factory=dict)


SYSTEM_PROMPT = (
    "You are a careful copywriter for small local service businesses. You write "
    "clean, concrete, plain website copy. You NEVER invent facts, awards, "
    "years in business, certifications, prices, offers, ratings or reviews. You "
    "only use what the business data and its customer reviews support. Plain, "
    "specific language beats adjectives: describe what the business does, not how "
    "good it is. Output valid JSON only, no commentary."
)

#: Words the prompt asks the model to avoid unless the input itself uses them.
#: The audit below is the actual control; this list just saves a retry.
_PROMPT_AVOID = (
    "expert, experienced, professional, trusted, reliable, dependable, "
    "high-quality, affordable, top-rated, best, leading, "
    "premier, decades, lifetime, 24/7, emergency, same-day, family-owned, "
    "locally owned, licensed, insured, bonded, certified, guaranteed, warranty, "
    "eco-friendly, lowest price, price match, hundreds, thousands, dozens, "
    "star ratings, review counts, percentages"
)


def _a(word: str) -> str:
    """Indefinite article for ``word`` ("an electrician", "a plumber")."""
    return "an" if (word or "x")[0].lower() in "aeiou" else "a"


def _build_prompt(business: Business, rejected: Optional[list[str]] = None) -> str:
    review_lines = []
    for r in business.reviews:
        review_lines.append(f"- {r.author}: {r.text}")
    reviews_block = "\n".join(review_lines) if review_lines else "(no reviews provided)"

    if business.offers_free_estimates:
        cta_hint = "e.g. 'Call for a free estimate'"
        free_rule = "- The business offers free estimates; you may say so."
    else:
        cta_hint = "e.g. 'Call for a quote'"
        free_rule = (
            "- Do NOT use the word 'free' anywhere. The business has not said it "
            "offers anything for free."
        )

    retry_block = ""
    if rejected:
        phrases = ", ".join(f"'{p}'" for p in rejected)
        retry_block = f"""
IMPORTANT -- your previous draft was rejected because it claimed things the
business data does not support: {phrases}. Write a new draft that does not use
those words or make those claims in any form. Do not replace them with
synonyms or other praise either (no "expert", "professional", "reliable",
"trusted", "quality" and so on): describe the work itself, using the
customers' own concrete details.
"""

    return f"""Business facts:
- Name: {business.name}
- Category: {business.category}
- City/service area: {business.city}
- Phone: {business.phone}
- Website: {business.website or "(none)"}
- Hours: {business.hours or "(not provided)"}

Customer reviews (use these ONLY to infer what the business does and what
customers value; do not quote or invent reviews -- testimonials are handled
separately):
{reviews_block}

Write website copy as JSON with exactly these keys:
{{
  "hero_headline": "short headline, <= 8 words, no exclamation marks",
  "hero_subhead": "one sentence, <= 22 words, concrete and plain",
  "services": [
    {{"title": "2-4 word service name", "description": "<= 16 words"}}
  ],
  "about": "2-3 plain sentences about the business, grounded in the facts and in what reviews describe. Do not invent history or credentials.",
  "cta_label": "short call-to-action button text, {cta_hint}"
}}

Rules:
- List 3 or 4 services, strictly ones the reviews describe the business doing.
  Describe each only as far as the reviews go: do not add product types,
  customer types or variants the reviews do not mention. Write service
  descriptions in the present tense as what the business does (e.g. "Repairs
  leaks in metal roofs"), never as a past job ("Replaced a roof on...").
- Mention the city/service area naturally.
- No statistics, ratings, review counts, awards, guarantees, credentials,
  prices or offers. No claims about speed or cost ("quickly", "fast",
  "low cost") unless a review says exactly that about that service.
- Every sentence must be something a customer review or the business facts
  directly state. If in doubt, leave it out. Write plain, natural English.
- Avoid these words unless the business facts or reviews use them: {_PROMPT_AVOID}.
{free_rule}
{retry_block}
Return ONLY the JSON object."""


def _fallback_content(business: Business) -> tuple[str, str, list[Service], str, str]:
    """Deterministic copy used when no LLM draft survives the audit.

    It states only what the input says: name, category, place, phone, hours.
    It must itself pass :func:`audit_copy` for any business -- a test runs it
    through the audit for several categories.
    """
    cat = business.category
    cat_lower = cat.lower()
    city = business.city
    headline = f"{cat} in {city}"
    subhead = (
        f"{business.name} is {_a(cat_lower)} {cat_lower} serving {city}. "
        "Read what customers say, then call to talk through your job."
    )
    if business.offers_free_estimates:
        quote = Service(
            "Free estimates",
            f"Call {business.phone} to describe the job and ask for a free estimate.",
        )
        cta = "Call for a free estimate"
    else:
        quote = Service(
            "Quotes",
            f"Call {business.phone} to describe the job and ask for a quote.",
        )
        cta = "Call for a quote"
    area = f"Based in {city}."
    if business.hours:
        area += f" Hours: {business.hours}."
    services = [
        Service(cat, f"{cat} serving customers in {city}."),
        quote,
        Service("Service area", area),
    ]
    about = (
        f"{business.name} is {_a(cat_lower)} {cat_lower} based in {city}. "
        f"The testimonials on this page are reproduced verbatim from customer "
        f"reviews supplied by {business.name}."
    )
    return headline, subhead, services, about, cta


def _coerce_services(raw) -> list[Service]:
    services: list[Service] = []
    if isinstance(raw, list):
        for item in raw:
            if isinstance(item, dict):
                title = str(item.get("title", "")).strip()
                desc = str(item.get("description", "")).strip()
            else:
                title = str(item).strip()
                desc = ""
            if title:
                services.append(Service(title=title, description=desc))
    return services[:4]


def _generate_copy(business: Business, model: str, endpoint: str, timeout: float,
                   rejected: Optional[list[str]] = None):
    """Return (copy_dict, used_llm: bool, note: str).

    ``rejected`` lists phrases a previous draft was thrown out for; they are fed
    back to the model so the retry knows what not to say.
    """
    prompt = _build_prompt(business, rejected)
    try:
        raw = llm.generate(
            prompt,
            model=model,
            endpoint=endpoint,
            timeout=timeout,
            system=SYSTEM_PROMPT,
            fmt="json",
        )
    except llm.LLMUnavailable as exc:
        return None, False, f"LLM unavailable, used fallback template: {exc}"

    # ollama with format=json should return clean JSON, but be defensive.
    text = raw.strip()
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if not match:
            return None, False, "LLM returned unparseable output, used fallback template"
        try:
            parsed = json.loads(match.group(0))
        except json.JSONDecodeError:
            return None, False, "LLM returned invalid JSON, used fallback template"

    services = _coerce_services(parsed.get("services"))
    headline = str(parsed.get("hero_headline", "")).strip()
    subhead = str(parsed.get("hero_subhead", "")).strip()
    about = str(parsed.get("about", "")).strip()
    cta = str(parsed.get("cta_label", "")).strip()

    if not (headline and subhead and services):
        return None, False, "LLM output incomplete, used fallback template"

    return (
        {
            "hero_headline": headline,
            "hero_subhead": subhead,
            "services": services,
            "about": about,
            "cta_label": cta or (
                "Call for a free estimate" if business.offers_free_estimates
                else "Call for a quote"
            ),
        },
        True,
        f"copy generated by {model}",
    )


# ---------------------------------------------------------------------------
# Unsupported-claim guard
# ---------------------------------------------------------------------------
# The system prompt tells the model not to invent credentials. Models do it
# anyway -- a 7B model produced "With over 20 years of experience" for a
# business whose input says nothing about its age. A prompt is not a control,
# so the output is checked: copy that asserts a credential, award, guarantee,
# offer or statistic the input does not support is thrown away (one retry with
# the rejected phrases fed back, then the deterministic template).
#
# Support-checking is deliberately crude and conservative: a matched phrase
# counts as supported only if the same words (or their simple singular/plural
# form) appear as a whole phrase, case-insensitively, somewhere in the
# business's own facts or reviews. That is not
# proof the claim is true -- a review saying "not the best" would "support"
# the word "best" -- it only guarantees the copy does not introduce a claim
# the input never mentioned. A human still has to review the page.
_CLAIM_PATTERNS: tuple[tuple[str, str], ...] = (
    (r"\b(?:over\s+|more\s+than\s+)?\d+\+?\s*years?\b", "years in business"),
    (r"\bdecades?\b", "years in business"),
    (r"\bsince\s+(?:19|20)\d{2}\b", "founding year"),
    (r"\b(?:fully\s+)?(?:licen[cs]ed|insured|bonded|certified|accredited)\b",
     "licensing/certification"),
    (r"\bcertifications?\b|\bmanufacturer[\s-]approved\b|\bOSHA\b",
     "licensing/certification"),
    (r"\bBBB\b|\bBetter\s+Business\s+Bureau\b|(?<![\w+])A\+(?![\w+])",
     "rating-agency claim"),
    (r"\baward[\s-]winning\b|\bawards?\b|\bvoted\b|\brated\s+#?\s?1\b"
     r"|\b#\s?1\b|\bnumber\s+one\b|\bbest\b|\btop[\s-]rated\b"
     r"|\bhighest[\s-]rated\b|\bleading\b|\bpremier\b", "award/ranking"),
    (r"\bexperts?\b|\bexpertise\b|\bexperienced\b|\bprofessionals?\b"
     r"|\bprofessionally\b", "expertise claim"),
    (r"\btrusted\b|\breliable\b|\breliability\b|\bdependable\b"
     r"|\btop[\s-]notch\b|\bhigh[\s-]quality\b|\btop[\s-]quality\b"
     r"|\bunmatched\b|\bunbeatable\b|\bunrivall?ed\b|\bworld[\s-]class\b"
     r"|\bstate[\s-]of[\s-]the[\s-]art\b", "reputation claim"),
    (r"\b24\s*/\s*7\b|\b24-7\b|\b24\s+hours?\b|\baround[\s-]the[\s-]clock\b"
     r"|\bemergenc(?:y|ies)\b|\bsame[\s-]day\b", "availability claim"),
    (r"\b(?:locally|family|veteran|woman|women|minority|independently)"
     r"[\s-](?:owned|run|operated)\b|\b\w+[\s-]generation\b", "ownership claim"),
    (r"\beco[\s-]?friendly\b|\benvironmentally[\s-]friendly\b", "environmental claim"),
    (r"\blowest\s+(?:prices?|rates?|costs?)\b|\bcheapest\b|\baffordable\b"
     r"|\bprice[\s-]match(?:ing|ed)?\b|\bbeat\s+any\s+(?:price|quote)s?\b",
     "price claim"),
    (r"\b\d{1,3}(?:\.\d+)?\s?%", "statistic"),
    (r"\b(?:hundreds|thousands|dozens|countless)\b", "volume claim"),
    (r"\b\d{1,3}(?:,\d{3})+\+?|\b\d{3,}\+?", "volume statistic"),
    (r"\b[0-5](?:\.\d)?[\s-]*stars?\b|\b[0-5]\.\d\b", "rating claim"),
    (r"\bguarantee[ds]?\b|\bwarrant(?:y|ies|ied)\b|\blifetime\b", "guarantee/warranty"),
    (r"\bfree\b", "free offer"),
)
_CLAIM_RES = tuple((re.compile(pat, re.IGNORECASE), label) for pat, label in _CLAIM_PATTERNS)


def _supporting_corpus(business: Business) -> str:
    """Everything the business actually told us, as one searchable blob."""
    parts = [business.name, business.category, business.city, business.phone,
             business.hours or "", business.website or ""]
    parts += [r.text for r in business.reviews]
    return " ".join(" ".join(p.split()) for p in parts).lower()


def _variants(phrase: str) -> set[str]:
    """The phrase plus its simple singular/plural forms ("emergencies" ->
    "emergency", "experts" -> "expert"), so a review saying one supports the
    other. Deliberately nothing cleverer than that."""
    p = phrase.lower()
    out = {p}
    if p.endswith("ies") and len(p) > 4:
        out.add(p[:-3] + "y")
    elif p.endswith("s") and not p.endswith("ss") and len(p) > 3:
        out.add(p[:-1])
    if p.endswith("y") and len(p) > 3:
        out.add(p[:-1] + "ies")
    elif not p.endswith("s"):
        out.add(p + "s")
    return out


def _supported(phrase: str, corpus: str) -> bool:
    return any(re.search(r"(?<![a-z0-9])" + re.escape(v) + r"(?![a-z0-9])", corpus)
               for v in _variants(phrase))


def unsupported_claims(text: str, corpus: str, *, allow_free: bool = False) -> list[dict]:
    """Claims in ``text`` that the supplied facts and reviews do not back up.

    A claim is treated as supported when the matched words also appear in the
    business's own input -- if a customer review says "20 years", the copy may
    say it too. "Free" is the exception: it is allowed only when the business
    explicitly sets ``offers_free_estimates``, because a review mentioning
    something free is not an offer the business makes to everyone.
    """
    found: list[dict] = []
    clean = " ".join((text or "").split())
    for rx, label in _CLAIM_RES:
        for m in rx.finditer(clean):
            phrase = m.group(0).strip()
            if label == "free offer":
                if allow_free:
                    continue
            elif _supported(phrase, corpus):
                continue
            found.append({"claim": phrase, "kind": label})
    return found


def audit_copy(copy: dict, business: Business) -> list[dict]:
    """Check every generated field for unsupported claims."""
    corpus = _supporting_corpus(business)
    problems: list[dict] = []
    fields = {
        "hero_headline": copy.get("hero_headline", ""),
        "hero_subhead": copy.get("hero_subhead", ""),
        "about": copy.get("about", ""),
        "cta_label": copy.get("cta_label", ""),
    }
    for svc in copy.get("services") or []:
        fields[f"service:{svc.title}"] = f"{svc.title}. {svc.description}"
    for field_name, text in fields.items():
        for issue in unsupported_claims(
            text, corpus, allow_free=business.offers_free_estimates
        ):
            problems.append({"field": field_name, **issue})
    return problems


def _fallback_as_copy(business: Business) -> dict:
    headline, subhead, services, about, cta = _fallback_content(business)
    return {"hero_headline": headline, "hero_subhead": subhead,
            "services": services, "about": about, "cta_label": cta}


def _truncate_verbatim(text: str, limit: int = TESTIMONIAL_MAX_CHARS) -> tuple[str, bool]:
    """Trim whitespace; if longer than limit, cut at a word boundary + ellipsis.

    The kept portion is a verbatim prefix of the real review -- we never reword.
    """
    clean = " ".join(text.split())
    if len(clean) <= limit:
        return clean, False
    cut = clean[:limit].rsplit(" ", 1)[0].rstrip(",.;:- ")
    return cut + "…", True


def _select_testimonials(business: Business) -> list[Testimonial]:
    """Pick up to MAX real reviews with substantive text, verbatim.

    Preference: reviews with meaningful text, higher ratings first, then longer
    text. Never fabricated -- every testimonial maps to a real review index.
    """
    candidates = [r for r in business.reviews if len(r.text.strip()) >= 15]
    candidates.sort(key=lambda r: (r.rating, len(r.text)), reverse=True)
    chosen = candidates[:MAX_TESTIMONIALS]

    testimonials: list[Testimonial] = []
    for r in chosen:
        text, truncated = _truncate_verbatim(r.text)
        testimonials.append(
            Testimonial(
                author=r.author,
                rating=r.rating,
                text=text,
                date=r.date,
                source_index=r.source_index,
                truncated=truncated,
                source_url=r.source_url,
            )
        )
    return testimonials


# ---------------------------------------------------------------------------
# Image resolution
# ---------------------------------------------------------------------------
def resolve_images(
    business: Business,
    out_dir: Optional[str],
    config: ImageConfig,
    *,
    service_slots: int = 3,
    on_progress: Optional[Callable[[str], None]] = None,
) -> ImageSet:
    """Decide what imagery the page gets, and obtain it.

    The policy, in order:

    1. ``mode="off"`` -> nothing.
    2. The business supplied photos (``mode`` in ``auto``/``own-only``) ->
       use **only** those. First photo is the hero, the rest form the gallery.
       Service cards stay text-only: a photo on a service card reads as "this
       is our work on that service", and the gallery already makes that claim
       once, honestly, in one place.
    3. No supplied photos and ``mode`` in ``auto``/``illustrative`` -> generate
       generic trade imagery for the hero and the service cards. **No
       gallery**: a grid of generated photos would read as a portfolio, which
       would be a lie. Captions are never attached.
    4. Generation unavailable -> no imagery, and ``info`` says why.

    A supplied logo is passed through. A logo is never generated.
    """
    info: dict = {"mode": config.mode}
    iset = ImageSet(info=info)

    if config.mode == "off":
        info["note"] = "imagery disabled (--images off)"
        return iset

    asset_dir = None
    if out_dir:
        import os

        asset_dir = os.path.join(out_dir, config.asset_subdir)

    if business.logo is not None:
        logo = business.logo
        if asset_dir:
            logo = images_mod.stage_supplied_photos(
                [logo], asset_dir, rel_prefix=config.asset_subdir,
                name_prefix="logo",
            )[0]
        iset.logo = logo
        info["logo"] = "supplied by the business"
    else:
        info["logo"] = (
            "none supplied; the renderer uses a typographic wordmark. "
            "ReviewForge never generates a logo."
        )

    own = business.own_photos
    if own and config.mode in ("auto", "own-only"):
        if asset_dir:
            own = images_mod.stage_supplied_photos(
                own, asset_dir, rel_prefix=config.asset_subdir
            )
        hero_candidates = [p for p in own if p.role == "hero"] or own
        hero = hero_candidates[0]
        hero.role = "hero"
        rest = [p for p in own if p is not hero]
        for p in rest:
            p.role = "gallery"
        iset.hero = hero
        iset.gallery = rest if len(rest) >= MIN_GALLERY_PHOTOS else []
        info["source"] = "business-supplied photos"
        info["supplied_photo_count"] = len(own)
        if rest and not iset.gallery:
            info["gallery"] = (
                f"omitted: only {len(rest)} photo(s) besides the hero "
                f"(need {MIN_GALLERY_PHOTOS})"
            )
        return iset

    if config.mode == "own-only":
        info["source"] = "none"
        info["note"] = (
            "the business supplied no photos and --images own-only forbids "
            "generated imagery, so the page is text-only"
        )
        return iset

    # --- illustrative fallback ------------------------------------------
    backend, backend_info = images_mod.resolve_backend(
        config.backend,
        comfyui_url=config.comfyui_url,
        checkpoint=config.checkpoint,
        timeout=config.timeout,
    )
    info["image_backend"] = backend_info
    if backend is None or asset_dir is None:
        info["source"] = "none"
        info["note"] = (
            "no image backend reachable, so the page is text-only rather than "
            "showing a picture we cannot honestly account for"
            if backend is None
            else "no output directory, so no imagery was generated"
        )
        return iset

    generated, failures = images_mod.generate_illustrative_images(
        business.category,
        asset_dir,
        backend=backend,
        rel_prefix=config.asset_subdir,
        service_count=max(config.service_count, service_slots),
        seed=config.seed,
        on_progress=on_progress,
    )
    if failures:
        info["generation_failures"] = failures
    info["source"] = "generated illustrative imagery"
    info["scene_set"] = images_mod.scene_key_for_category(business.category)

    for img in generated:
        if img.role == "hero" and iset.hero is None:
            iset.hero = img
        else:
            img.role = "service"
            iset.service_images.append(img)

    # Hard guard, not a convention: nothing illustrative may reach the gallery.
    iset.gallery = [img for img in iset.gallery if img.is_business_own]
    return iset


_WORD_RE = re.compile(r"[a-z]+")
#: Words that carry no signal when matching a service name to an image.
_STOPWORDS = frozenset(
    "a an and the of for in on at to with your our new clean close detail "
    "shot wide view photograph image plain soft light daylight work works "
    "service services expert quality professional custom all types home "
    "homes house houses".split()
)


def _keywords(text: str) -> set[str]:
    words = {w for w in _WORD_RE.findall((text or "").lower()) if len(w) > 2}
    words -= _STOPWORDS
    # Crude singularisation so "gutters" matches "gutter".
    return {w[:-1] if w.endswith("s") and len(w) > 4 else w for w in words}


def _overlap(svc_words: set[str], img_words: set[str]) -> int:
    """Count service words matched by an image's alt text.

    Prefix matching on words of four characters or more, so "roofing" matches
    "roof" -- without it, a metal-roof photo and a roofing-tools photo tie on
    "Metal Roofing" and the tie is broken arbitrarily.
    """
    hits = 0
    for w in svc_words:
        for v in img_words:
            if w == v or (
                len(w) >= 4 and len(v) >= 4 and (w.startswith(v) or v.startswith(w))
            ):
                hits += 1
                break
    return hits


def _assign_service_images(
    services: list[Service], pool: list[SiteImage]
) -> None:
    """Put each illustrative image on the service card it actually depicts.

    Positional assignment produced cards like "Siding Repair" illustrated with
    a gutter. The imagery is disclosed as illustrative either way, but a
    mismatch still makes the page look careless, so each image goes to the
    service whose name best overlaps its (generic) alt text; leftovers fall
    back to filling the remaining cards in order.
    """
    remaining = list(pool)
    unfilled = list(services)
    while remaining and unfilled:
        best = None  # (score, service_idx, image_idx)
        for si, service in enumerate(unfilled):
            svc_words = _keywords(f"{service.title} {service.description}")
            for ii, img in enumerate(remaining):
                score = _overlap(svc_words, _keywords(img.alt))
                if score and (best is None or score > best[0]):
                    best = (score, si, ii)
        if best is None:
            break
        _score, si, ii = best
        unfilled.pop(si).image = remaining.pop(ii)
    # Anything left over simply fills the remaining cards in order.
    for service, img in zip(unfilled, remaining):
        service.image = img


#: Shown verbatim in the page footer whenever any illustrative image appears.
#: Deliberately apostrophe-free so it survives HTML-escaping unchanged and can
#: be asserted on byte-for-byte in the rendered page.
ILLUSTRATIVE_DISCLOSURE = (
    "The images on this page were generated by software as placeholders. "
    "They are not photographs of work completed by this business."
)


def generate_site_content(
    business: Business,
    *,
    model: str = llm.DEFAULT_MODEL,
    endpoint: str = llm.DEFAULT_ENDPOINT,
    timeout: float = llm.DEFAULT_TIMEOUT,
    out_dir: Optional[str] = None,
    image_config: Optional[ImageConfig] = None,
    on_progress: Optional[Callable[[str], None]] = None,
) -> SiteContent:
    """Produce validated, honest SiteContent for a business.

    Raises :class:`~reviewforge.models.LegalRequirementError` when the
    business's jurisdiction requires legal pages that were not supplied.
    """
    legal_warnings = business.legal_warnings()

    copy, used_llm, note = _generate_copy(business, model, endpoint, timeout)
    rejected_claims: list[dict] = []
    attempts: list[dict] = []
    if copy is not None:
        problems = audit_copy(copy, business)
        attempts.append({"attempt": 1, "rejected_claims": problems})
        if problems:
            # The model asserted something the input does not support. Drop
            # the whole draft (copy that invented one credential is not
            # trusted for the rest) and give it exactly one more try, telling
            # it which phrases were rejected.
            rejected_claims.extend({**p, "attempt": 1} for p in problems)
            phrases = sorted({p["claim"] for p in problems}, key=str.lower)
            if on_progress:
                on_progress(f"copy draft rejected ({', '.join(phrases)}); retrying once")
            copy, used_llm, retry_note = _generate_copy(
                business, model, endpoint, timeout, rejected=phrases
            )
            if copy is not None:
                problems2 = audit_copy(copy, business)
                attempts.append({"attempt": 2, "rejected_claims": problems2})
                if problems2:
                    rejected_claims.extend({**p, "attempt": 2} for p in problems2)
                    copy, used_llm = None, False
                else:
                    note = (
                        f"{retry_note}; first draft rejected for unsupported "
                        f"claims ({', '.join(repr(p) for p in phrases)}), "
                        "second draft passed the audit"
                    )
            else:
                attempts.append({"attempt": 2, "error": retry_note})
            if copy is None:
                summary = ", ".join(
                    f"{c['claim']!r} ({c['kind']}) in {c['field']}"
                    for c in rejected_claims[:6]
                )
                note = (
                    "LLM copy rejected: it asserted facts the business data does "
                    f"not support -- {summary}. Used fallback template."
                )
    fallback = copy is None
    if fallback:
        copy = _fallback_as_copy(business)
        services_heading = f"Working with {business.name}"
        services_intro = ""
    else:
        services_heading = "What we do"
        services_intro = f"Services {business.name} provides in {business.city}."

    headline = copy["hero_headline"]
    subhead = copy["hero_subhead"]
    services = copy["services"]
    about = copy["about"]
    cta = copy["cta_label"]

    testimonials = _select_testimonials(business)

    # Default is deliberately conservative: use the business's own photos if it
    # has any, but never reach out to an image backend unless the caller asked.
    cfg = image_config or ImageConfig(mode="own-only")
    iset = resolve_images(
        business,
        out_dir,
        cfg,
        service_slots=len(services),
        on_progress=on_progress,
    )

    # Attach service imagery, matched to the service it depicts. Only ever
    # illustrative imagery lands here (see resolve_images), and SiteImage
    # guarantees it cannot carry an ownership caption.
    _assign_service_images(services, iset.service_images)

    rs = business.rating_summary
    if rs is not None:
        rating_basis = {
            "basis": "rating_summary supplied by the business",
            "average": rs.average, "count": rs.count, "platform": rs.platform,
        }
    elif testimonials:
        rating_basis = {
            "basis": "average of the reviews shown on the page",
            "average": shown_rating_average(testimonials),
            "count": len(testimonials),
        }
    else:
        rating_basis = None

    provenance = {
        "tool": "reviewforge",
        "copy_source": "llm" if used_llm else "fallback_template",
        "llm_model": model if used_llm else None,
        "llm_endpoint": llm.describe_endpoint(endpoint) if used_llm else None,
        "note": note,
        "copy_attempts": attempts,
        "rejected_claims": rejected_claims,
        "claim_check": (
            "Conservative pattern match; a flagged phrase passes only if the "
            "same words (or a simple plural/singular) appear in the supplied "
            "facts or reviews. It blocks claims the input never "
            "mentions; it does not prove any claim true. Human review required."
        ),
        "offers_free_estimates": business.offers_free_estimates,
        "reviews_supplied": business.review_count,
        "reviews_used_as_testimonials": [
            {
                "source_index": t.source_index,
                "author": t.author,
                "rating": t.rating,
                "truncated": t.truncated,
                "source_url": t.source_url,
            }
            for t in testimonials
        ],
        "rating_display": rating_basis,
        "country": business.country,
        "legal": {
            "impressum": bool(business.legal.impressum),
            "privacy": bool(business.legal.privacy),
            "warnings": legal_warnings,
        },
        "photos_supplied": len(business.photos),
        "images": [img.to_provenance() for img in iset.all_images],
        "image_resolution": iset.info,
        "uses_illustrative_imagery": iset.uses_illustrative,
        "illustrative_disclosure": (
            ILLUSTRATIVE_DISCLOSURE if iset.uses_illustrative else None
        ),
        "honesty": (
            "Testimonials are verbatim prefixes of reviews supplied by the "
            "business, with the author and rating as supplied; ReviewForge "
            "cannot verify that a supplied review is genuine. Marketing copy "
            "(hero/services/about) is LLM- or template-generated and is "
            "rejected if it asserts a credential, award, offer, guarantee or "
            "statistic the supplied business data and reviews do not mention. "
            "Every image is listed above with its origin; any image not "
            "supplied by the business is flagged illustrative, kept out of the work gallery, carries neutral alt "
            "text and no ownership caption, and is disclosed in the page "
            "footer. Generated image files are written without embedded "
            "generation metadata; those details are recorded here instead."
        ),
    }

    return SiteContent(
        business=business,
        hero_headline=headline,
        hero_subhead=subhead,
        services=services,
        about=about,
        cta_label=cta,
        testimonials=testimonials,
        images=iset,
        provenance=provenance,
        services_heading=services_heading,
        services_intro=services_intro,
    )


def shown_rating_average(testimonials: list[Testimonial]) -> Optional[float]:
    """Average star rating of the testimonials actually shown on the page."""
    if not testimonials:
        return None
    return round(sum(t.rating for t in testimonials) / len(testimonials), 1)


def provenance_json(content: SiteContent) -> str:
    return json.dumps(content.provenance, indent=2, ensure_ascii=False)
